ST.xhtml:p:
R_Trigger(CLK := bFHomeEnable OR g_biFHomeEnable);
IF bChangeHomeMode THEN
  bChangeHomeMode := FALSE;
  nChangeHomeModeState := 1;
END_IF;

IF R_Trigger.Q THEN
  nFHomeSwitch := 1;
  bFHomeEnable := false;
  g_bFHomeDone := false;
  g_boFHomeDone := false;
END_IF;

CASE nFHomeSwitch OF
  0:
    nFHomeSwitch := 0;
  1:
     g_FHome.Execute := true;
     IF nFHomingMode = 0 THEN
      g_FHome.HomingMode := 0;
      g_FHome.Position := dFHomePosition;
      g_FHome.DISTANCE:= dFHomeOffset;
    ELSIF nFHomingMode = 1 THEN
      g_FHome.HomingMode := 5;
      g_FHome.Position := 0.0;
    ELSIF nFHomingMode = 2 THEN
      g_FHome.HomingMode := 4;
      g_FHome.Position := 0.0;
    ELSIF nFHomingMode = 3 THEN
      (*只是去掉回零标志位*)
      g_FHome.HomingMode := 1;
    END_IF;

    g_FHome.bCalibrationCam := g_bFAxisZero;
    IF g_FHome.Done THEN
      g_FHome.Execute := FALSE;
      g_bFHomeDone := true;
      g_boFHomeDone := true;
      nFHomeSwitch := 0;
    END_IF;

    IF g_bPlcPauseBuffer THEN
      nFHomeSwitch := 20;
    END_IF;
    IF g_FHome.CommandAborted OR g_FHome.Error THEN
      g_FHome.Execute := FALSE;
      nFHomeSwitch := 0;
    END_IF;
    20:
      g_FHome.Execute := FALSE;
      g_FAbsolute.Execute := FALSE;
      g_FPause.Execute := TRUE;
      IF g_FPause.Done AND g_bPlcStartBuffer THEN
        g_FPause.Execute := FALSE;
        nFHomeSwitch := 1;
      END_IF;
      IF g_FPause.CommandAborted OR g_FPause.Error THEN
        g_FPause.Execute := FALSE;
        nFHomeSwitch := 0;
      END_IF; 
END_CASE;

CASE nChangeHomeModeState OF
  0:
    nChangeHomeModeState := 0;
  1:
    g_FHome.Execute := TRUE;
    IF nFHomingMode = 0 THEN
      g_FHome.HomingMode := 0;
    ELSIF nFHomingMode = 1 THEN
      g_FHome.HomingMode := 5;
    ELSIF nFHomingMode = 2 THEN
      g_FHome.HomingMode := 4;
    END_IF;
      g_FHome.Position := 0.0;
      g_FHome.DISTANCE:= 0.0;
    IF g_FHome.Done THEN
      g_FHome.Execute := FALSE;
      nChangeHomeModeState := 0;
    END_IF;
    IF g_FHome.CommandAborted OR g_FHome.Error THEN
      g_FHome.Execute := FALSE;
      nChangeHomeModeState := 0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nFHomeSwitch := 0;
  nChangeHomeModeState := 0;
  g_bFHomeDone := true;
  g_boFHomeDone := true;
  g_FAbsolute.Execute := FALSE;
  g_FHome.Execute := false;
  g_FPause.Execute := false;
END_IF;
  g_nFHomeMode := nFHomingMode;
